        "content": "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: m20-web\n  namespace: kv-lab\n  labels:\n    lab: m20\nspec:\n  replicas: 2\n  selector:\n    matchLabels:\n      app: m20-web\n  template:\n    metadata:\n      labels:\n        app: m20-web\n        lab: m20\n    spec:\n      containers:\n        - name: web\n          image: nginx:1.28.0-alpine\n          ports:\n            - containerPort: 80\n          resources:\n            requests:\n              cpu: 10m\n              memory: 16Mi\n            limits:\n              cpu: 250m\n              memory: 64Mi\n---\napiVersion: v1\nkind: Service\nmetadata:\n  name: m20-web\n  namespace: kv-lab\n  labels:\n    lab: m20\nspec:\n  selector:\n    app: broken-selector\n  ports:\n    - port: 80\n      targetPort: 80\n---\napiVersion: v1\nkind: Pod\nmetadata:\n  name: m20-client\n  namespace: kv-lab\n  labels:\n    lab: m20\nspec:\n  terminationGracePeriodSeconds: 1\n  containers:\n    - name: app\n      image: busybox:1.37.0\n      command:\n        - sh\n        - -c\n        - sleep 3600\n"
